//! Utilities used by mocks generated by [`crate::service`].
//!
//! Generated mocks implement the corresponding stub traits, so they can be
//! passed to code under test without opening a network connection. Configure
//! expected calls and notifications when constructing a mock. Expectations are
//! matched in the order they are registered, and the mock verifies that all
//! expectations were fulfilled when it is dropped.
//!
//! # Example
//!
//! ```rust
//! mod services {
//!     #[rpc_genie::service]
//!     pub mod service {
//!         sub_services! {
//!             pub child_service: super::child_service,
//!         }
//!
//!         pub struct Server<Stream> {}
//!
//!         pub struct Client<Stream> {}
//!
//!         impl<Stream> Server<Stream> {
//!             #[remote_method]
//!             pub fn _do_stuff(_arg: u32) -> String {
//!                 unreachable!("mocks don't use the real implementation");
//!             }
//!         }
//!     }
//!
//!     #[rpc_genie::service]
//!     pub mod child_service {
//!         pub struct Server<Stream> {}
//!
//!         pub struct Client<Stream> {}
//!
//!         impl<Stream> Server<Stream> {
//!             #[remote_method]
//!             pub fn _ping(_arg: String) -> String {
//!                 unreachable!("mocks don't use the real implementation");
//!             }
//!         }
//!     }
//! }
//!
//! use services::*;
//! use service::ServerStub as _;
//! use child_service::ServerStub as _;
//! use rpc_genie::SendSingleRequest as _;
//!
//! async fn function_to_test(server_stub: &impl service::ServerStub) {
//!     assert_eq!("hey".to_owned(), server_stub._do_stuff(1).call().await.unwrap());
//!     assert_eq!("heyy".to_owned(), server_stub._do_stuff(2).call().await.unwrap());
//!
//!     assert_eq!(
//!         "foo".to_owned(),
//!         server_stub.child_service()
//!             ._ping("foo".to_owned())
//!             .call()
//!             .await
//!             .unwrap()
//!     );
//!
//!     server_stub._do_stuff(3).notify().await.unwrap();
//! }
//!
//! #[tokio::main]
//! // assume main() is a unit test for function_to_test()
//! async fn main() {
//!     // create a mock
//!     let mock = service::ServerStubMock::new(|expectation_setter| {
//!         // Makes the mock expect a call of _do_stuff() with arg 1
//!         expectation_setter
//!             ._do_stuff(1)
//!             .call()
//!             // Sets the return value
//!             .returns("hey".to_owned());
//!
//!         expectation_setter
//!             ._do_stuff(2)
//!             .call()
//!             .returns("heyy".to_owned());
//!
//!         expectation_setter
//!             // Can also add expectations to the sub-services
//!             .child_service()
//!             ._ping("foo".to_string())
//!             .call()
//!             .returns("foo".to_owned());
//!
//!         // Expectations can also be .notify() not just .call()
//!         expectation_setter._do_stuff(3).notify();
//!     });
//!
//!     // pass the mock to any functions that takes the corresponding stub trait
//!     function_to_test(&mock).await;
//!
//!     // When mock is dropped it will check that all expected methods have been called and panic
//!     // otherwise
//!     drop(mock);
//! }
//! ```

use std::{
    assert_matches,
    fmt::Display,
    marker::PhantomData,
    sync::{Arc, Mutex, PoisonError},
};

use crate::SendSingleRequest;

#[doc(hidden)]
#[derive(Default)]
pub struct Expectations(Vec<Expectation>);

struct Expectation {
    method_path: String,
    encoded_args: Box<[String]>,
    return_value: Option<String>,
}

#[must_use = "should use either `.call().returns(..)` or `.notify()` to add the expectation"]
/// Configures whether a generated mock method is expected to call or notify.
pub struct ExpectationSetter<'a, ReturnValue> {
    #[doc(hidden)]
    pub method_path: String,
    #[doc(hidden)]
    pub encoded_args: Box<[String]>,
    #[doc(hidden)]
    pub expectations: &'a Mutex<Expectations>,
    #[doc(hidden)]
    pub return_value: PhantomData<fn() -> ReturnValue>,
}

#[must_use = "should use `.returns(..)` to add the expectation"]
/// Configures the return value for an expected mock call.
pub struct ExpectationCallSetter<'a, ReturnValue>(
    ExpectationSetter<'a, ReturnValue>,
    PhantomData<fn() -> ReturnValue>,
);

#[doc(hidden)]
pub struct MockSingleRequestSender<ReturnValue>
where
    ReturnValue: serde::de::DeserializeOwned,
{
    #[doc(hidden)]
    pub method_path: String,
    #[doc(hidden)]
    pub encoded_args: Box<[String]>,
    #[doc(hidden)]
    pub expectations: Arc<Mutex<Expectations>>,
    #[doc(hidden)]
    pub return_value: PhantomData<fn() -> ReturnValue>,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum InvocationType {
    Call,
    Notify,
}

impl Display for InvocationType {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            InvocationType::Call => write!(f, "call"),
            InvocationType::Notify => write!(f, "notify"),
        }
    }
}

impl Display for Expectation {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(
            f,
            "{}",
            describe_expectation(
                &self.method_path,
                &self.encoded_args,
                match self.return_value {
                    Some(_) => InvocationType::Call,
                    None => InvocationType::Notify,
                }
            )
        )
    }
}

impl std::fmt::Debug for Expectation {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{self}")
    }
}

fn describe_expectation(
    method_path: &str,
    args: &[String],
    invocation_type: InvocationType,
) -> String {
    let method_path = method_path.replace("/", "().");
    let args = args.join(",");
    format!("mock.{method_path}({args}).{invocation_type}()")
}

impl Expectations {
    fn push(
        &mut self,
        method_path: String,
        encoded_args: Box<[String]>,
        return_value: Option<String>,
    ) {
        self.0.push(Expectation {
            method_path,
            encoded_args,
            return_value,
        })
    }

    fn take_next(
        &mut self,
        method_path: &str,
        args: &[String],
        invocation_type: InvocationType,
    ) -> Expectation {
        if self.0.is_empty() {
            panic!(
                "Found {} when no more usages of the mock were expected",
                describe_expectation(method_path, args, invocation_type)
            );
        }

        let expectation = self.0.remove(0);

        expectation.assert_matches(method_path, args, invocation_type);

        expectation
    }
}

impl Drop for Expectations {
    fn drop(&mut self) {
        if self.0.is_empty() || std::thread::panicking() {
            return;
        }

        panic!(
            "Mock was dropped with the following expectations unmet: {:?}",
            self.0
        );
    }
}

impl Expectation {
    fn assert_matches(&self, method_path: &str, args: &[String], invocation_type: InvocationType) {
        let panic_with_msg = || {
            panic!(
                "Expected {self}, found {}",
                describe_expectation(method_path, args, invocation_type)
            )
        };

        if self.method_path != method_path {
            panic_with_msg();
        }

        match &self.return_value {
            None if invocation_type == InvocationType::Call => panic_with_msg(),
            Some(_) if invocation_type == InvocationType::Notify => panic_with_msg(),
            _ => {}
        }

        for (expected_arg, arg) in self.encoded_args.iter().zip(args.iter()) {
            if expected_arg != arg {
                panic_with_msg();
            }
        }
        if self.encoded_args.len() != args.len() {
            panic!("Internal rpc-genie error: mock expected_args len is not equal args len");
        }
    }
}

impl<ReturnValue> SendSingleRequest<ReturnValue> for MockSingleRequestSender<ReturnValue>
where
    ReturnValue: serde::de::DeserializeOwned,
{
    async fn call(self) -> Result<ReturnValue, crate::CallError> {
        let expectation = self
            .expectations
            .lock()
            .unwrap_or_else(PoisonError::into_inner)
            .take_next(&self.method_path, &self.encoded_args, InvocationType::Call);

        let return_value = expectation.return_value.expect(
            "Internal rpc-genie error: \
             InvocationType::Call will never have return_value at None inside mock",
        );

        Ok(decode_value(&return_value))
    }

    async fn notify(self) -> Result<(), crate::NotifyError> {
        let expectation = self
            .expectations
            .lock()
            .unwrap_or_else(PoisonError::into_inner)
            .take_next(
                &self.method_path,
                &self.encoded_args,
                InvocationType::Notify,
            );

        assert_matches!(
            expectation.return_value,
            None,
            "Internal rpc-genie error: \
             InvocationType::Notify should always have return_value at None inside mock"
        );

        Ok(())
    }
}

impl<'a, ReturnValue> ExpectationSetter<'a, ReturnValue> {
    /// Adds an expectation that the method is called and returns a value.
    pub fn call(self) -> ExpectationCallSetter<'a, ReturnValue> {
        ExpectationCallSetter(self, PhantomData)
    }

    /// Adds an expectation that the method is sent as a notification.
    pub fn notify(self) {
        self.expectations
            .lock()
            .unwrap_or_else(PoisonError::into_inner)
            .push(self.method_path, self.encoded_args, None)
    }
}

impl<'a, ReturnValue> ExpectationCallSetter<'a, ReturnValue>
where
    ReturnValue: serde::Serialize,
{
    /// Sets the value returned by the expected call.
    pub fn returns(self, return_value: ReturnValue) {
        self.0
            .expectations
            .lock()
            .unwrap_or_else(PoisonError::into_inner)
            .push(
                self.0.method_path,
                self.0.encoded_args,
                Some(encode_value(return_value)),
            )
    }
}

#[doc(hidden)]
pub fn encode_value<Value>(value: Value) -> String
where
    Value: serde::Serialize,
{
    ron::to_string(&value).expect("Internal rpc-genie error: Failed to encode value for mock")
}

fn decode_value<Value>(value: &str) -> Value
where
    Value: serde::de::DeserializeOwned,
{
    ron::from_str(value).expect("Internal rpc-genie error: Failed to decode value for mock")
}
